#!/bin/bash
# Generates .opencode/opencode.json — the stack config (MCP + skills)
# for the given directory.
#
# The stack activates ONLY in projects where this file is generated.
# The global ~/.config/opencode is never used by the stack.
#
# Paths are written ABSOLUTE: the stack can live anywhere
# ($STACK_DIR, ~/any-folder/stack, ...), and the config binds to
# its real location at generation time. If the stack moves —
# paths are rewritten by regeneration: bash <stack>/sync-agents.sh
# ({env:HOME} remains only for the user-level Wolfram directories).
#
# Usage:
#   bash gen-opencode-config.sh <target-folder>   # required argument
set -euo pipefail

# Stack root = the folder containing this script
STACK_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"

TARGET="${1:-}"
if [ -z "$TARGET" ]; then
    echo "Usage: $0 <target-folder>"; exit 1
fi

mkdir -p "$TARGET/.opencode"

# ── Wolfram: the binary is resolved on this machine (the path is not
# portable, but the config is always regenerated by gen-opencode-config.sh /
# sync-agents.sh). Candidates: Wolfram Engine, Wolfram Desktop, Wolfram Research (alpha numbering).
WOLFRAM_BIN=""
for cand in \
    "/Applications/Wolfram Engine.app/Contents/Resources/Wolfram Player.app/Contents/MacOS/wolfram" \
    /Applications/Wolfram*.app/Contents/Resources/Wolfram\ Player.app/Contents/MacOS/wolfram \
    /Applications/Wolfram*.app/SystemFiles/FrontEnd/Executables/MacOSX/WolframKernel; do
    if [ -x "$cand" ]; then
        WOLFRAM_BIN="$cand"
        break
    fi
done
# Fallback: the kernel usually sits next to wolframscript
if [ -z "$WOLFRAM_BIN" ] && command -v wolframscript &>/dev/null; then
    WS_DIR="$(cd "$(dirname "$(command -v wolframscript)")/.." && pwd)"
    KERN=$(find "$WS_DIR" -name wolfram -type f -perm +111 2>/dev/null | head -1)
    [ -n "$KERN" ] && WOLFRAM_BIN="$KERN"
fi
if [ -z "$WOLFRAM_BIN" ]; then
    echo "  ⚠️ Wolfram kernel not found — keeping the default path (check manually)"
    WOLFRAM_BIN="/Applications/Wolfram Engine.app/Contents/Resources/Wolfram Player.app/Contents/MacOS/wolfram"
fi

# WOLFRAM_BASE = the Resources dir of the root .app (replaces the nonexistent /Library/WolframEngine).
# Structure: Wolfram Engine.app/Contents/Resources/Wolfram Player.app/Contents/MacOS/wolfram
WOLFRAM_BASE=""
DIR="$(dirname "$WOLFRAM_BIN")"
while [ "$DIR" != "/" ]; do
    if [ "$(basename "$DIR")" = "Contents" ]; then
        CAND="$(dirname "$(dirname "$DIR")")/Contents/Resources"
        [ -d "$CAND" ] && WOLFRAM_BASE="$CAND" && break
    fi
    DIR="$(dirname "$DIR")"
done
[ -n "$WOLFRAM_BASE" ] || WOLFRAM_BASE="/Applications/Wolfram Engine.app/Contents/Resources"

# ── MCP server entry points: known name first, discovery fallback
# (upstream renames of server.py / manim_server.py / dist/index.js
# should not produce a silently broken config)
resolve_mcp_file() {
    local repo=$1 known=$2 pattern=$3
    local f="$STACK_DIR/$repo/$known"
    [ -f "$f" ] && { echo "$f"; return; }
    find "$STACK_DIR/$repo" -maxdepth 3 -name "$pattern" 2>/dev/null | head -1
}
JULIA_SERVER=$(resolve_mcp_file julia-mcp server.py 'server.py')
MANIM_SERVER=$(resolve_mcp_file manim-mcp src/manim_server.py '*server*.py')
TLDRAW_ENTRY=$(resolve_mcp_file tldraw-mcp dist/index.js 'index.js')
[ -n "$JULIA_SERVER" ]  || echo "  ⚠️ julia-mcp server not found — julia MCP will fail until re-cloned"
[ -n "$MANIM_SERVER" ]  || echo "  ⚠️ manim server not found — manim MCP will fail until re-cloned"
[ -n "$TLDRAW_ENTRY" ]  || echo "  ⚠️ tldraw-mcp dist/index.js not found — tldraw MCP will fail until rebuilt"
: "${JULIA_SERVER:=$STACK_DIR/julia-mcp/server.py}"
: "${MANIM_SERVER:=$STACK_DIR/manim-mcp/src/manim_server.py}"
: "${TLDRAW_ENTRY:=$STACK_DIR/tldraw-mcp/dist/index.js}"

cat > "$TARGET/.opencode/opencode.json" << 'CONF'
{
  "__SCHEMA__": "https://opencode.ai/config.json",
  "skills": ["__STACK__/skills-store"],
  "mcp": {
    "servers": {
    "Wolfram": {
      "type": "local",
      "command": [
        "__WOLFRAM_BIN__",
        "-run",
        "PacletSymbol[\"Wolfram/AgentTools\",\"Wolfram`AgentTools`StartMCPServer\"][]",
        "-noinit",
        "-noprompt"
      ],
      "enabled": true,
      "environment": {
        "MCP_SERVER_NAME": "WolframLanguage",
        "WOLFRAM_BASE": "__WOLFRAM_BASE__",
        "WOLFRAM_LOCALBASE": "{env:HOME}/Library/Wolfram/Objects",
        "WOLFRAM_USERBASE": "{env:HOME}/Library/WolframEngine"
      },
      "timeout": 240000
    },
    "julia": {
      "type": "local",
      "command": ["__STACK__/julia-mcp-env/bin/python", "__JULIA_SERVER__"],
      "enabled": true,
      "timeout": 60000
    },
    "manim": {
      "type": "local",
      "command": ["__STACK__/manim-env/bin/python", "__MANIM_SERVER__"],
      "environment": {"PATH": "__STACK__/manim-env/bin:__BREWBIN__:/usr/bin:/bin:/usr/sbin:/sbin"},
      "enabled": true,
      "timeout": 120000
    },
    "ParaView": {
      "type": "local",
      "command": ["bash", "__STACK__/scripts/paraview-run.sh"],
      "enabled": true,
      "timeout": 60000
    },
    "tldraw": {
      "type": "local",
      "command": ["node", "__TLDRAW_ENTRY__"],
      "enabled": true,
      "timeout": 60000
    },
    "wordcraft": {
      "type": "local",
      "command": ["__STACK__/craft-cli/wordcraft-cli", "mcp"],
      "enabled": true,
      "timeout": 120000
    },
    "gridcraft": {
      "type": "local",
      "command": ["__STACK__/craft-cli/gridcraft-cli", "mcp"],
      "enabled": true,
      "timeout": 120000
    },
    "deckcraft": {
      "type": "local",
      "command": ["__STACK__/craft-cli/deckcraft-cli", "mcp"],
      "enabled": true,
      "timeout": 120000
    },
    "pdfcraft": {
      "type": "local",
      "command": ["__STACK__/craft-cli/pdfcraft-cli", "mcp"],
      "enabled": true,
      "timeout": 120000
    },
    "figcraft": {
      "type": "local",
      "command": ["__STACK__/craft-cli/figcraft-cli", "mcp"],
      "enabled": true,
      "timeout": 120000
    }
    }
  }
}
CONF

# Substitute the computed paths (quoted heredoc keeps {env:HOME} intact)
PVAPP="$(ls -d /Applications/ParaView*.app 2>/dev/null | head -1)"
PV_PYLIB="$(ls -d "$PVAPP/Contents/Libraries"/lib/python3.* 2>/dev/null | sort -V | tail -1)"
BREWBIN="$(dirname "$(command -v brew 2>/dev/null)" 2>/dev/null)"
[ -n "$BREWBIN" ] || BREWBIN="/opt/homebrew/bin"
sed -i '' \
    -e "s|__WOLFRAM_BIN__|$WOLFRAM_BIN|g" \
    -e "s|__SCHEMA__|\$schema|g" \
    -e "s|__WOLFRAM_BASE__|$WOLFRAM_BASE|g" \
    -e "s|__STACK__|$STACK_DIR|g" \
    -e "s|__JULIA_SERVER__|$JULIA_SERVER|g" \
    -e "s|__MANIM_SERVER__|$MANIM_SERVER|g" \
    -e "s|__TLDRAW_ENTRY__|$TLDRAW_ENTRY|g" \
    -e "s|__PARAVIEW_PYTHON__|$PVAPP/Contents/Python|g" \
    -e "s|__PARAVIEW_PYLIB__|${PV_PYLIB:-$PVAPP/Contents/Libraries/lib/python3.12}|g" \
    -e "s|__PARAVIEW_LIBS__|$PVAPP/Contents/Libraries|g" \
    -e "s|__PARAVIEW_FRAMEWORKS__|$PVAPP/Contents/Frameworks|g" \
    -e "s|__BREWBIN__|$BREWBIN|g" \
    "$TARGET/.opencode/opencode.json"

# JSON validation

echo "  OpenCode config: $TARGET/.opencode/opencode.json"
